 */
scwin.ClearLog = function() {
    // txaMain.Text = "";

};

// 화면 UI 로그 조회 함수 (개발시에만 로그조회를 위해  txaMain textarea 컴포넌트를 추가하여 사용.)

/**
 * @method
 * @name SetLog
