// ▼ component resize 시작부(화면크기 변경시 그리드, 조회버튼의 위치및 크기변경)
frame.SetEvent("onwinstat", OnWinStat);
scwin.gOldWidthSize = frame.width;

/**
 * @method
 * @name OnSized
 * @description On Sized 처리
 * @param {String} winID winID
 * @returns {void}
 * @hidden N
 */
scwin.OnSized = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    scwin.GauceObjResize(frame.width, frame.height);
};

/**
 * @method
 * @name OnSizedMax
 * @description On Sized Max 처리
 * @param {String} winID winID
 * @returns {void}
 * @hidden N
 */
scwin.OnSizedMax = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    scwin.GauceObjResize($c.frame.path("/").width, frame.height);
};

/**
 * @method
 * @name OnWinStat
 * @description On Win Stat 처리
 * @param {String} winID winID
 * @param {*} statmsg statmsg
 * @returns {void}
 * @hidden N
 */
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg === "activate" && winID.substring(0, 6) === "Child_") {
        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg === "maximize") {
        scwin.maxval = 1;
    } else if (statmsg === "size") {
        if (scwin.maxval === 0) {
            const strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval === 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};

/**
 * @method
 * @name GauceObjResize
 * @description Gauce Obj Resize 처리
 * @param {*} a a
 * @param {*} b b
 * @returns {void}
 * @hidden N
 */
scwin.GauceObjResize = function(a, b) {
    const gw = (a - parseInt(grd_main.getStyle("width")) - 50);
    grd_item.ReDraw = "false";
    grd_item.setGridWidth(parseInt(grd_item.getStyle("width")) + gw); // 상단그리드
    grd_item.ReDraw = "true";
    image_11.style.left = parseInt(image_11.style.left.replace("px", "")) + gw; // 상단패널이미지바
    btn_search.style.left = parseInt(btn_search.style.left.replace("px", "")) + gw; // 상단검색버튼
    const pnl_main_grp = document.all("__GROUPBOX_BACKGROUND__" + "pnl_main");
    pnl_main_grp.style.setGridWidth(parseInt(pnl_main_grp.style.width.replace("px", "")) + gw); // 상단패널
    grd_main.ReDraw = "false";
    grd_main.setGridWidth(parseInt(grd_main.getStyle("width")) + gw); // 하단그리드
    grd_main.ReDraw = "true";
    pnl_content.style.width = parseInt(pnl_content.style.width.replace("px", "")) + gw; // 하단컨텐트패널
    btn_excel.style.left = parseInt(btn_excel.style.left.replace("px", "")) + gw; // 하단엑셀버튼
    scwin.gOldWidthSize = frame.width;
};

// ▲ component resize 종료부(화면크기 변경시 그리드, 조회버튼의 위치및 크기변경)

/**
 * @method
 * @name ShowWin2
 * @description 로딩이미지 보이기
 * @param {*} sval sval
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ShowWin2 = async function(sval) {
    if ($c.frame.path("NoData") !== null) {
        await $c.win.closePopup();
    }
    if ($c.frame.path("LoadingImg2") !== null) {
        await $c.win.closePopup();
    }
    let tem1 = sval.style.getStyle("width");
    let temLeft = sval.style.left;
    let temTop = sval.style.top;
    let tem2 = sval.style.getStyle("height");
    tem1 = tem1.substring(0, (tem1.length - 2));
    temLeft = temLeft.substring(0, (temLeft.length - 2));
    tem2 = tem2.substring(0, (tem2.length - 2));
    temTop = temTop.substring(0, (temTop.length - 2));
    vXpos = ((tem1 / 2) - 65) + Number(temLeft);
    vYpos = ((tem2 / 2) - 18) + Number(temTop);
    if ($c.frame.path("LoadingImg2") === null) {
        await $c.frame.CreateFrame("LoadingImg2", "/common/LoadingImg.gfm", "페이지 로딩중...", vXpos, vYpos, 130, 35, "sunken", 0, 0, true);
    }
};

/**
 * @method
 * @name CloseWin2
 * @description 로딩이미지 숨기기
 * @param {Number} cnt cnt
 * @param {*} sval sval
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.CloseWin2 = async function(cnt, sval) {
    if ($c.frame.path("LoadingImg2") !== null) {
        await $c.win.closePopup();
        if (cnt === 0) $c.cm.ShowNoData(sval);
    }
};

/**
 * @method
 * @name setCode
 * @description 부서코드, 사원코드 세팅
 * @returns {Promise<void>}
 * @hidden N
 */
