/**
 * @method
 * @name getVersion
 * @description 해당기간, 서식코드의 버전별 건수 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getVersion = async function() {
    if (txb_form_cd.getValue() === "") {
        await $c.win.alert("[공시제목]을 선택하세요.");
        return;
    }
    /**********************************************************
     * - 2018.03.28 수정 :  버튼   클릭 안되게 처리                            *
     **********************************************************/
    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_search.setDisabled(true);
    btn_search.setBackgroundImage("../img/btn_select_d.gif");
    url_all += "&FORM_CD=" + txb_form_cd.getValue();
    url_all += "&FORM_VER=" + cmb_form_ver.getValue();
    url_all += "&SDATE=" + edt_sdate.getValue();
    url_all += "&EDATE=" + edt_edate.getValue();
    url_all += "&ISUR_CD=" + txb_isur_cd.getValue();
    url_all += "&DEP_CD=" + cmb_dep_cd.getValue();
    url_all += "&EMP_NO=" + cmb_emp_no.getValue();
    url_all += "&LIST_STAT_CD=" + chb_list_stat_cd.getValue();
    url_all += "&LAST_YN=" + chk_last.getValue();
    url_all += "&SUBCOM_DISCLS_EX_YN=" + chk_branch.getValue();
    url_all += "&MKT_ID=" + rdo_mkt_id.getValue();
    const sbmOptions = {
        id : "sbm_dts_form_ver",
        action : "/NewDisclosureStatistics.do",
        ref : "",
        target : "dts_form_ver=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    scwin.gDtsFormVerDuringTransaction = true;

    await scwin.ShowWin2(grd_item);
};

/**
 * @method
 * @name startPreview
 * @description 상단그리드 다시 그리기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.startPreview = async function() {
    if (txb_form_cd.getValue() === "") {
        await $c.win.alert("[공시제목]을 선택하세요.");
        return;
    }
    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_search.setDisabled(true);
    btn_search.setBackgroundImage("../img/btn_select_d.gif");
    dts_form_ver.getRowCount();
    let vStr = dts_form_ver.getCellData(cmb_form_ver.getSelectedIndex() + 1, 2);
    if (scwin.getVersionCount(vStr) !== '0') {
        // 건수가 존재하면 http request
        await scwin.getHeaderItemsExcludeTuple();
    } else {
        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        btn_search.setDisabled(false);
        btn_search.setBackgroundImage("../img/btn_select.gif");
    }
};

/**
 * @method
 * @name setFromToDate2
 * @description 공시일자 10년 조회추가를 위한 공통함수 변형
 * @param {String} pTp pTp
 * @param {*} pObjFrom pObjFrom
 * @param {*} pObjTo pObjTo
 * @returns {void}
 * @hidden N
 */
scwin.setFromToDate2 = function(pTp, pObjFrom, pObjTo) {
    let vFrom = "";
    let vTo = pObjTo.getValue();
    if (vTo === '') {
        vTo = $c.ut.cGetToday("yyyymmdd");
    }
    if (pTp === 1) {
        vFrom = $c.ut.cGetMinusDate2(vTo, 7);
    } else if (pTp === 2) {
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 1);
    } else if (pTp === 3) {
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 3);
    } else if (pTp === 4) {
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 6);
    } else if (pTp === 5) {
        vFrom = $c.ut.cGetMinusYear(vTo, 1);
    } else if (pTp === 6) {
        vFrom = $c.ut.cGetMinusYear(vTo, 2);
    } else if (pTp === 7) {
        vFrom = $c.ut.cGetMinusYear(vTo, 5);
    }
    pObjFrom.setValue(vFrom);
    pObjTo.setValue(vTo);
};

/**
 * @method
 * @name locateVer
 * @description 서식버전콤보박스 리스트 中  건수가 존재하는 서식버전으로 위치시키기
 * @returns {void}
 * @hidden N
 */
scwin.locateVer = function() {
    let isExist = false;
    let vStr = "";
    for (let i = 1; i < dts_form_ver.getRowCount() + 1; i++) {
        vStr = dts_form_ver.getCellData(i, 2);
        if (scwin.getVersionCount(vStr) !== 0) {
            isExist = true;
            if (i !== 0) {
                cmb_form_ver.setSelectedIndex(i - 1);
            } else {
                cmb_form_ver.setSelectedIndex(i);
            }
            break;
        }
    }

    // 모든버전의 건수가 0일때
    if (isExist === false) {
        cmb_form_ver.setSelectedIndex(0);
    }
};

/**
 * @method
 * @name getVersionCount
 * @description "5.01(100)"과 같은 서식버전문자열을 입력받아 괄호안에 숫자를 리턴
 * @param {*} vString vString
 * @returns {void}
 * @hidden N
 */
scwin.getVersionCount = function(vString) {
    let verCount = /\([0-9]+\)/g.exec(vString);
    verCount = verCount[0].replace("(", "").replace(")", "");
    return verCount;
};

/**
 * @method
 * @name getHeaderItemsExcludeTuple
 * @description 서식항목 가져오기 (튜플 제외) 상단그리드헤더 그릴때 사용
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getHeaderItemsExcludeTuple = async function() {
    if (txb_form_cd.getValue() === "") return;

    // 서식콤보 변경될때 메인그리드 내용 없앨지 남겨둘지
    // dts_main.ClearAll();

    url_all += "&FORM_CD=" + txb_form_cd.getValue();
    url_all += "&FORM_VER=" + cmb_form_ver.getValue();
    const sbmOptions = {
        id : "sbm_dts_item_header_ex",
        action : "/NewDisclosureStatistics.do",
        ref : "",
        target : "dts_item_header_ex=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name toDateObject
 * @description YYYYMMDD 문자열을 Date 객체로 변환
 * @param {String} vDateStr vDateStr
 * @returns {void}
 * @hidden N
 */
scwin.toDateObject = function(vDateStr) {
    const year = vDateStr.substr(0, 4);
    const month = vDateStr.substr(4, 2);
    const day = vDateStr.substr(6, 2);
    const hour = "00";
    let min = "00";
    return new Date(year, month, day, hour, min);
};

/**
 * @method
 * @name getMonthInterval
 * @description 월수차이계산
 * @param {String} vSDateStr vSDateStr
 * @param {String} vEDateStr vEDateStr
 * @returns {void}
 * @hidden N
 */
scwin.getMonthInterval = function(vSDateStr, vEDateStr) {
    const date1 = scwin.toDateObject(vSDateStr);
    const date2 = scwin.toDateObject(vEDateStr);
    const years = date2.getFullYear() - date1.getFullYear();
    const months = date2.getMonth() - date1.getMonth();
    const days = date2.getDate() - date1.getDate();
    return (years * 12 + months + (days >= 0 ? 0 : -1));
};

/**
 * @method
 * @name expectHugeDataSize
 * @description 사용자입력공시일자와 해당서식버전의 공시일자의 범위가 10년이 넘거나 건수가 2천건을 초과하는 경우
 * @returns {void}
 * @hidden N
 */
scwin.expectHugeDataSize = function() {
    const userDateGap = scwin.getMonthInterval(edt_sdate.getValue(), edt_edate.getValue()); // 사용자입력 공시일자의 범위(월수)
    const formDateGap = scwin.getMonthInterval(dts_form_ver.getCellData(cmb_form_ver.getSelectedIndex() + 1, "STRT_DD"), dts_form_ver.getCellData(cmb_form_ver.getSelectedIndex() + 1, "END_DD")); // 서식버전의 공시일자 범위(월수)
    const countRow = scwin.getVersionCount(dts_form_ver.getCellData(cmb_form_ver.getSelectedIndex() + 1, 2));
    if ((userDateGap >= 120 && formDateGap >= 120) || countRow > 3000) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name searchMain
 * @description 하단그리드 메인조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchMain = async function() {
    if (scwin.gDtsFormVerDuringTransaction) {
        await $c.win.alert("현재 버전별 접수건수를 가져오고 있습니다.  잠시기다려 주십시오.");
        return false;
    }
    if (dts_form_ver.getCellData(1, 1) === "F") {
        await $c.win.alert("해당보고서의 버전건수가 없습니다.");
        return false;
    }
    if (dts_item_header_ex.getRowCount() <= 0) {
        await $c.win.alert("선택된 추출항목이 없습니다..");
        return false;
    }
    if (scwin.expectHugeDataSize()) {
        await $c.win.alert("일자범위가 너무 길거나 해당 서식버전의 건수가 많아서 조회할 수 없습니다. 기간을 줄여주십시오.");
        return false;
    }

    /**********************************************************
     * - 2018.03.28 수정 : 주석처리, fn_GetVersion() 수행시 버튼   *
     *                                클릭 안되게 처리                                     *
     **********************************************************/
    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    // btn_search.disabled = true;
    // btn_search.src = "../img/btn_select_d.gif";

    await scwin.ShowWin2(grd_main);
    scwin.gSDate = new Date();
