 * @description 상단그리드 체크박스를 위한 1줄짜리 Dummy Record 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setItemGridHeaderCheck = function() {
    let headerString = "";
    headerString += "ROW_NO:STRING(1),DISCLS_PROCS_DDTM:STRING(1),ORG_DISCLS_DDTM:STRING(1),ISU_SRT_CD:STRING(1),MKT_NM:STRING(1),LIST_STAT_CD:STRING(1),LIST_STAT_NM:STRING(1),COM_NM:STRING(1),SUBCOM_DISCLS_YN:STRING(1),DEP_NM:STRING(1),EMP_NM:STRING(1),SNDLOC_TP_NM:STRING(1),";
    for (let i = 1; i < dts_item_header_ex.getRowCount() + 1; i++) {
        if (i === dts_item_header_ex.getRowCount()) {
            headerString += dts_item_header_ex.getCellData(i, "ACODE") + ":STRING(1)";
        } else {
            headerString += dts_item_header_ex.getCellData(i, "ACODE") + ":STRING(1),";
        }
    }
    scwin.SetLog("dummy set header string", headerString);
