 * @hidden N
 */
scwin.itemGridSelectAll = function() {
    grd_main.ReDraw = "false";
    grd_item.ReDraw = "false";
    dts_item_dummy.setBroadcast(false);
    for (let i = 1; i <= dts_item_dummy.getTotalCol() + 1; i++) {
        dts_item_dummy.setCellData(1, dts_item_dummy.getColumnID(i - 1));
    }
    dts_item_dummy.setBroadcast(true, true);
    $c.cm.setColumnProp(grd_main, "ROW_NO", 'Show', "true");
