// 상단,하단그리드 항목계층한글명 그리기(보고서별 동적생성)

/**
 * @method
 * @name setMultiHeader
 * @description 기본헤더
 * @param {*} grdObj grdObj
 * @param {*} headerObj headerObj
 * @returns {void}
 * @hidden N
 */
scwin.setMultiHeader = function(grdObj, headerObj) {
    // 기본헤더
    scwin.setBasicHeader(grdObj);

    // Delimiter
    const DELIMITER = "`";
    const INDENTATION = "    ";
    const LINEFEED = "\n";
    // Grid Style
    if (grdObj === grd_main) {
        let GRID_STYLE_CTAG = " width=100 headbgcolor=\"#598fd5\" headcolor=\"#ffffff\" color=\"#343434\" bgcolor=\"{decode(currow-tointeger(currow/2)*2,0,'#f2f5f9',1,'#ffffff')}\"";
        let GRID_STYLE_XTAG = " headbgcolor=\"#598fd5\" headcolor=\"#ffffff\"";
    } else {
        let GRID_STYLE_CTAG = " width=100 editstyle='checkbox' headbgcolor=\"#598fd5\" headcolor=\"#ffffff\"";
        let GRID_STYLE_XTAG = " editstyle='checkbox' headbgcolor=\"#598fd5\" headcolor=\"#ffffff\"";
    }
    // grid format 계층태그상수
    const LEVEL_ONE_BEGIN_TAG = "<C>";
    const LEVEL_ONE_END_TAG = "</C>\n";
    const LEVEL_TWO_BEGIN_TAG = "<G>";
    const LEVEL_TWO_END_TAG = "</G>\n";
    const LEVEL_THREE_BEGIN_TAG = "<X>";
    const LEVEL_THREE_END_TAG = "</X>\n";
    // 엘리먼트한글명 기억변수
    let oldEleKorNm = "";
    let newEleKorNm = "";
    // ACODE 기억변수
    let newAcode = "";
    // 엘리먼트한글명 계층배열 기억변수
    let oldArrEleKorNm = "";
    let newArrEleKorNm = "";
    // 그리드포멧결과
    let gridFormat = "";
    // 헤더의 Depth 정보(디폴트 : 1레벨)
    let oldHeaderDepth = 1;
    let newHeaderDepth = 1;
    let maxDepth = 0;
    // 최고 depth 검사
    for (i = 1; i < headerObj.getRowCount() + 1; i++) {
        newHeaderDepth = headerObj.getCellData(i, "ELMT_CLSS_NM").split(DELIMITER).length;
        if (maxDepth < newHeaderDepth) {
            maxDepth = newHeaderDepth;
        }
    }
    scwin.SetLog("레벨최고길이", maxDepth);
    newHeaderDepth = 0; // 초기화
    for (i = 1; i < headerObj.getRowCount() + 1; i++) {
        if (grdObj === grd_main) {
            newAcode = headerObj.getCellData(i, "ACODE");
        } else {
            // 항목그리드는 ACODE에 space값을 제거해야 check가 활성화된다. (dataset에서 헤더설정하면서 space가 자동제거됨)
            newAcode = headerObj.getCellData(i, "ACODE").replace(" ", "");
        }
        newEleKorNm = headerObj.getCellData(i, "ELMT_CLSS_NM");
        newArrEleKorNm = newEleKorNm.split(DELIMITER);
        newHeaderDepth = newArrEleKorNm.length;
        oldArrEleKorNm = oldEleKorNm.split(DELIMITER);
        oldHeaderDepth = oldArrEleKorNm.length;

        // 이전 TAG 종료
        if ((oldHeaderDepth === 2) && (oldArrEleKorNm[0] !== newArrEleKorNm[0])) {
            if (maxDepth <= 2) {
                gridFormat += LEVEL_TWO_END_TAG;
            } else {
                gridFormat += LEVEL_THREE_END_TAG;
            }
        }
        if (oldHeaderDepth >= 3) {
            if (oldArrEleKorNm[1] !== newArrEleKorNm[1]) {
                gridFormat += INDENTATION + LEVEL_TWO_END_TAG;
            }
            if (oldArrEleKorNm[0] !== newArrEleKorNm[0]) {
                gridFormat += LEVEL_THREE_END_TAG;
            }
        }
        // 1레벨 엘리먼트 한글명 출력
        if (newHeaderDepth === 1) {
            gridFormat += LEVEL_ONE_BEGIN_TAG;
            gridFormat += "id=\"" + newAcode + "\"" + " name=\"" + newArrEleKorNm[0] + "\"" + GRID_STYLE_CTAG;
            gridFormat += LEVEL_ONE_END_TAG;
        }
        // 2레벨 엘리먼트 한글명 출력
        else if (newHeaderDepth === 2) {
            if ((oldArrEleKorNm[0] !== newArrEleKorNm[0]) || (oldHeaderDepth < 2)) {
                if (maxDepth <= 2) {
                    gridFormat += LEVEL_TWO_BEGIN_TAG;
                } else {
                    gridFormat += LEVEL_THREE_BEGIN_TAG;
                }
                gridFormat += "name=\"" + newArrEleKorNm[0] + "\"" + GRID_STYLE_XTAG + LINEFEED;
            }
            gridFormat += INDENTATION + LEVEL_ONE_BEGIN_TAG;
            gridFormat += "id=\"" + newAcode + "\"" + " name=\"" + newArrEleKorNm[1] + "\"" + GRID_STYLE_CTAG;
            gridFormat += LEVEL_ONE_END_TAG;
        }
        // 3레벨 엘리먼트 한글명 출력
        else if (newHeaderDepth >= 3) {
            if (oldArrEleKorNm[0] !== newArrEleKorNm[0]) {
                gridFormat += LEVEL_THREE_BEGIN_TAG;
                gridFormat += "name=\"" + newArrEleKorNm[0] + "\"" + GRID_STYLE_XTAG + LINEFEED;
                gridFormat += INDENTATION + LEVEL_TWO_BEGIN_TAG;
                gridFormat += "name=\"" + newArrEleKorNm[1] + "\"" + GRID_STYLE_XTAG + LINEFEED;
            } else {
                if (oldArrEleKorNm[1] !== newArrEleKorNm[1]) {
                    gridFormat += LEVEL_TWO_BEGIN_TAG;
                    gridFormat += "name=\"" + newArrEleKorNm[1] + "\"" + GRID_STYLE_XTAG + LINEFEED;
                }
            }
            gridFormat += INDENTATION + INDENTATION + LEVEL_ONE_BEGIN_TAG;
            gridFormat += "id=\"" + newAcode + "\"" + " name=\"" + newArrEleKorNm[2] + "\"" + GRID_STYLE_CTAG;
            gridFormat += LEVEL_ONE_END_TAG;
        }
        // EOF일때 2레벨 이상의 이전 태그 종료
        if (i === headerObj.getRowCount()) {
            scwin.SetLog("EOF Check", i + "//" + headerObj.getRowCount());
            if (newHeaderDepth === 2) {
                if (maxDepth <= 2) {
                    gridFormat += LEVEL_TWO_END_TAG;
                } else {
                    gridFormat += LEVEL_THREE_END_TAG;
                }
            }
            if (newHeaderDepth >= 3) {
                gridFormat += INDENTATION + LEVEL_TWO_END_TAG;
                gridFormat += LEVEL_THREE_END_TAG;
            }
        }
        oldEleKorNm = newEleKorNm;
    }
    if (grdObj === grd_main) {
        gridFormat += "<C> width=0 headbgcolor=\"#598fd5\" headcolor=\"#ffffff\" color=\"#343434\" bgcolor=\"{decode(currow-tointeger(currow/2)*2,0,'#f2f5f9',1,'#ffffff')}\"";
        gridFormat += " headbgcolor=\"#598fd5\" headcolor=\"#ffffff\"";
        gridFormat += " name='공시뷰어URL' id='VIEWER_URL'</C>\n";
    }
    grdObj.Format += gridFormat;
    scwin.SetLog("그리드포멧" + grdObj, grdObj.Format);
};

