/**
 * @method
 * @name dts_item_header_in_OnLoadCompleted
 * @description 튜플항목을 모두 받아온 후에 메인 검색 시작
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_item_header_in_OnLoadCompleted = async function(rowcount) {
    // 튜플항목을 모두 받아온 후에 메인 검색 시작
    if (scwin.findUncheckItem()) {
        for (let i = 1; i < dts_item_dummy + 1; i++) {
            const colid = dts_item_dummy.getColumnID(i - 1);
            grd_main.Redraw = false;
            scwin.checkDisclsItems(colid);
            grd_main.Redraw = true;
        }
    } else {
        scwin.setMultiHeader(grd_main, dts_item_header_in);
    }
    const FORM_CD = txb_form_cd.getValue();
    if (FORM_CD === "") {
        await $c.win.alert("[공시]를 선택하세요.");
        return;
    }
    const SDATE = edt_sdate.getValue();
    const EDATE = edt_edate.getValue();
    if (SDATE === "") {
        await $c.win.alert("[공시일자 - 시작일]을 입력하세요.");
        return;
    }
    if (EDATE === "") {
        await $c.win.alert("[공시일자 - 종료일]을 입력하세요.");
        return;
    }
    let selectedItems = scwin.getSelectedItems();
    if ("" === selectedItems) {
        await $c.win.alert("조회하고자 하는 항목을 선택하세요.");
        return;
    }
    url += "&FORM_CD=" + FORM_CD;
    url += "&FORM_VER=" + cmb_form_ver.getValue();
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;
    url += "&SFDATE=" + dts_form_ver.getCellData(cmb_form_ver.getSelectedIndex() + 1, "STRT_DD");
    url += "&EFDATE=" + dts_form_ver.getCellData(cmb_form_ver.getSelectedIndex() + 1, "END_DD");
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&DEP_CD=" + cmb_dep_cd.getValue();
    url += "&EMP_NO=" + cmb_emp_no.getValue();
    url += "&LIST_STAT_CD=" + chb_list_stat_cd.getValue();
    url += "&LAST_YN=" + chk_last.getValue();
    url += "&MKT_ID=" + rdo_mkt_id.getValue();
    url += "&SUBCOM_DISCLS_EX_YN=" + chk_branch.getValue();
    url += "&SCREN_ID=" + 'ULDSTF25007.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    scwin.SetLog("mainsearch request", url);
    const sbmOptions = {
        id : "sbm_dts_main",
        action : "/NewDisclosureStatistics.do",
        ref : "",
        target : "dts_main=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name dts_main_OnLoadCompleted
 * @description dts_main 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_main_OnLoadCompleted = async function(rowcount) {
    // alert(dts_main.ExportData(1,1,false));
    scwin.gEDate = new Date();
    scwin.gETimer = scwin.gEDate.getTime();
    const dispTimer = (scwin.gETimer - scwin.gSTimer) / 1000;
    let min = Math.round(dispTimer / 60, 2);
    const sec = Math.round(dispTimer % 60);
    let vCntMsg;
    if (rowcount !== scwin.getVersionCount(dts_form_ver.getCellData(cmb_form_ver.getSelectedIndex() + 1, 2))) {
        vcolor = "#ff0000";
        vCntMsg = $c.stf.FormatNumberEx(rowcount) + '(접수건과 추출건 불일치)';
    } else {
        vcolor = "#5c8be0";
        vCntMsg = $c.stf.FormatNumberEx(rowcount);
    }
    const vTotalArea = "<span style='font-size__9pt; font-family:굴림; color:#212863;'>추출건수: </span><span style='font-size__9pt; font-family:굴림; color:" + vcolor + "; font-weight:bold'>" + vCntMsg + "</span>";
    panel_page.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='100%'>" + "    <tr>" + "        <td align='left' width='2%' nowrap>" + vTotalArea + "</td>" + "        <td align='center'></td>" + "        <td align='right' width='30'></td>" + "        <td align='right' width='2%' nowrap>&nbsp;</td>" + "    </tr>" + "</table>";
    let dtsSize = dts_main.getTotalCol() * 3;
    for (let j = 1; j < dts_main.getTotalCol() + 1; j++) {
        dtsSize = dtsSize + dts_main.ColumnSize(j);
    }
    dtsSize = dtsSize * rowcount;
    const posV = Math.pow(10, 2);
    scwin.gDtsSize = Math.round(dtsSize / 1024 / 1024 * posV) / posV;
    panel_size.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='100%'>" + "    <tr>" + "        <td align='left' width='2%' nowrap><span style='font-size__9pt; font-family:굴림; color:#FFFFFF; font-weight:bold'>패킷 크기 : " + scwin.gDtsSize + "MBytes, 펫치 건수 : " + $c.stf.FormatNumberEx(rowcount * dts_main.getTotalCol()) + " 건</span></td>" + "        <td align='center'></td>" + "        <td align='right' width='30'></td>" + "        <td align='right' width='2%' nowrap>&nbsp;</td>" + "    </tr>" + "</table>";
    $c.stf.panelMsg(panel_msg, "처리시간 : " + min + " 분 " + sec + "초");

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_search.setDisabled(false);
    btn_search.setBackgroundImage("../img/btn_select.gif");
    await scwin.CloseWin2(rowcount, grd_main);
};

/**
 * @method
 * @name dts_emp_no_OnFilter
