        return (vVal === vVal2) ? true : false;
    }
};

/**
 * @method
 * @name btn_excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_excel_onclick = async function() {
    if (txb_form_cd.getValue() === "") {
        await $c.win.alert("[공시제목]을 선택하세요.");
        return;
    }
    $c.stf.doLogSave('ULDSTF25007.xml', SCREN_PROCS_TP_CD_07);
    let file_name = txb_form_kor_nm.getValue();
    const today = $c.ut.cGetToday('yyyymmddhhmmss');
    file_name = file_name.replace(/\//g, "");
    const xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
    file_name = file_name.substring(0, 30); // 오류 : GridToExcel-SheetName 길이가 31 이상이 될 수 없습니다.

    if (scwin.compareVersion(grd_main)) {
        $c.data.downloadGridViewOffice(grd_main, file_name, xls_path, "8", 0);
    } else {
        $c.data.downloadGridViewExcel(grd_main, {fileName: file_name, type: "8"});
    }
};

