 * @description grd main On Scrolling 처리
 * @param {Number} row 행 인덱스
 * @param {*} col col
 * @param {*} fromSetScrolling fromSetScrolling
 * @returns {void}
 * @hidden N
 */
scwin.grd_main_OnScrolling = function(row, col, fromSetScrolling) {
    if (fromSetScrolling === false) {
        if (col === 0) {
            grd_item.SetScrolling(row, 0);
        } else {
            grd_item.SetScrolling(row, col);
        }
    }
};

/**
 * @method
 * @name grd_main_onkeyup
 * @description grd_main 키 입력 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.grd_main_onkeyup = function(row, colid, data) {
    if (data === 67) {
        window.clipboardData.setData("TEXT", dts_main.getCellData(dts_main.getRowPosition(), "ACPT_NO"));
    }
};

/**
 * @method
 * @name btn_getversion_onclick
 * @description 「Refresh」 클릭 이벤트
