 */
scwin.gform_onload = async function() {
    $c.cm.PanelToGroupBox(pnl_main);
    await scwin.setCode();
    scwin.init();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_nm);
    edt_sdate.setValue($c.ut.calcMonth($c.ut.cGetToday2(), -3));
    edt_edate.setValue($c.ut.cGetToday2());
};

